    QCOMPARE(lineModule->params["line"].toArray().at(3).toDouble(), 60.0);
    QCOMPARE(lineModule->params.value(QStringLiteral("pick_coordinate_frame")).toString(),
             QStringLiteral("ImageLocalPixel"));

